tools.post_process_code:
try:
    result.pop('header', None)
    d = result.get('data')
    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':
        vars['close_outcome'] = 'not_reached'
        vars['close_reason'] = 'callback'
        vars['call_state'] = 'callback_booked'
        d['what_to_do_next'] = 'Booked. The call now ends automatically.'
    elif isinstance(d, dict):
        d['what_to_do_next'] = 'Not booked. Call schedule_callback once more with the same time.'
    else:
        result['what_to_do_next'] = 'Not booked. Call schedule_callback once more with the same time.'
except Exception:
    pass

try:
    result.pop('header', None)
    d = result.get('data')
    if isinstance(d, dict):
        if str(d.get('all_verified')).lower() == 'true':
            vars['id_state'] = 'passed'
            d['what_to_do_next'] = 'Identity verified. Say nothing; the account loads automatically.'
        elif d.get('hint') == 'day_month_swapped':
            d['what_to_do_next'] = 'Ask the customer to say the month of birth in words. This retry does not count as wrong.'
        elif str(d.get('wrong_answers_left')) == '0':
            vars['id_state'] = 'failed'
            d['what_to_do_next'] = 'The check failed. Say nothing about any account.'
        elif str(d.get('verified')).lower() == 'true':
            d['what_to_do_next'] = 'Correct. Now ask for the last four digits of the registered phone number.'
        elif str(d.get('ok')).lower() == 'false' and d.get('wrong_answers_left') is None:
            d['what_to_do_next'] = 'The answer could not be read. Ask the same question again.'
        else:
            d['what_to_do_next'] = 'That answer is not correct. Ask the same question once more.'
    else:
        result['what_to_do_next'] = 'The check did not work. Call verify_identity again with the same answer.'
except Exception:
    pass

tools.pre_process_code:
try:
    b = config.get('body')
    if isinstance(b, dict):
        b['product_id'] = vars.get('product_id') or b.get('product_id')
        a = str(b.get('amount')).replace(' ', '')
        if ',' in a:
            a = a.replace('.', '').replace(',', '.')
        b['amount'] = round(float(a), 2)
        b['date'] = str(b.get('date') or '').strip()[:10]
except Exception:
    pass

tools.post_process_code:
try:
    result.pop('header', None)
    d = result.get('data')
    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':
        vars['promise_count'] = str(int(vars.get('promise_count') or 0) + 1)
        vars['close_outcome'] = 'promise'
        vars['close_reason'] = ''
        vars['call_state'] = 'promised'
        d['what_to_do_next'] = 'Recorded. Say nothing; the confirmation is spoken automatically.'
    else:
        n = int(vars.get('promise_fail') or 0) + 1
        vars['promise_fail'] = str(n)
        if n >= 2:
            vars['close_outcome'] = 'no_promise'
            vars['close_reason'] = 'service_error'
            vars['call_state'] = 'promise_failed'
            msg = 'Not recorded. Say nothing; the call ends automatically.'
        else:
            msg = 'Not recorded. Call create_promise once more right now with the same values. Do not say it was recorded.'
        if isinstance(d, dict):
            d['what_to_do_next'] = msg
        else:
            result['what_to_do_next'] = msg
except Exception:
    pass

