try:
    result.pop('header', None)
    d = result.get('data')
    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'
    if ok:
        q = vars.get('transfer_queue') or 'general'
        vars['close_outcome'] = 'transferred'
        vars['close_reason'] = {'restructuring': 'restructuring', 'support': 'support'}.get(q, 'human')
        vars['call_state'] = 'transferred'
        d['what_to_do_next'] = 'Transferred. Say nothing; the call ends automatically.'
    elif isinstance(d, dict):
        d['what_to_do_next'] = 'The transfer failed. Call transfer_to_agent once more with the same queue.'
    else:
        result['what_to_do_next'] = 'The transfer failed. Call transfer_to_agent once more with the same queue.'
except Exception:
    pass

