try:
    b = config.get('body')
    if isinstance(b, dict):
        if vars.get('call_state') == 'transferred':
            b['outcome'] = 'transferred'
            b['reason'] = vars.get('close_reason') or 'human'
        elif int(vars.get('promise_count') or 0) > 0:
            b['outcome'] = 'promise'
        if b.get('outcome') in ('promise', 'paid') or not b.get('reason') or '{' in str(b.get('reason')):
            b.pop('reason', None)
        if not b.get('outcome') or '{' in str(b.get('outcome')):
            b['outcome'] = 'not_reached'
            b['reason'] = 'unclear'
except Exception:
    pass
